import{_ as i,a0 as p,w as r,s as g,ao as o,I as t,x as a,a1 as n,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"在 Linux 系统中手动滚动日志 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 系统中手动滚动日志 | LCTT (202003) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 系统中手动滚动日志 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 系统中手动滚动日志 | LCTT (202003) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202003/20200319 Manually rotating log files on Linux","title":"在 Linux 系统中手动滚动日志","tag":"202003","desc":""},"relativePath":"202003/20200319 Manually rotating log files on Linux.md","filePath":"[post].md"}'),d={name:"202003/20200319 Manually rotating log files on Linux.md"};function c(h,s,u,k,y,b){const l=p("Link");return r(),g("div",null,[s[20]||(s[20]=o('<h1 id="在-linux-系统中手动滚动日志" tabindex="-1">在 Linux 系统中手动滚动日志 <a class="header-anchor" href="#在-linux-系统中手动滚动日志" aria-label="Permalink to “在 Linux 系统中手动滚动日志”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202003/25/223932xqibwq5fafx5ao3f.jpg" alt=""></p><p><ruby>日志滚动<rt>log rotation</rt></ruby>在 Linux 系统上是再常见不过的一个功能了，它为系统监控和故障排查保留必要的日志内容，同时又防止过多的日志造成单个日志文件太大。</p><p>日志滚动的过程是这样的：在一组日志文件之中，编号最大的（最旧的）一个日志文件会被删除，其余的日志文件编号则依次增大并取代较旧的日志文件，而较新的文件则取代它作为当前的日志文件。这一个过程很容易就可以实现自动化，在细节上还能按需作出微调。</p><p>使用 <code>logrotate</code> 命令可以手动执行日志滚动的操作。本文将要介绍的就是手动进行日志滚动的方法，以及预期产生的结果。</p><p>文中出现的示例适用于 Ubuntu 等 Linux 系统，对于其它类型的系统，日志文件和配置文件可能会有所不同，但日志滚动的过程是大同小异的。</p><h3 id="为什么需要滚动日志" tabindex="-1">为什么需要滚动日志 <a class="header-anchor" href="#为什么需要滚动日志" aria-label="Permalink to “为什么需要滚动日志”">​</a></h3><p>一般情况下，无需手动旋转日志文件。Linux 系统会每隔一天（或间隔更长的时间）或根据日志文件的大小自动进行一次日志滚动。如果你需要滚动日志以释放存储空间，又或者将某一部分日志从当前的活动中分割出来，这很容易做到，具体要取决于文件滚动规则。</p><h3 id="一点背景介绍" tabindex="-1">一点背景介绍 <a class="header-anchor" href="#一点背景介绍" aria-label="Permalink to “一点背景介绍”">​</a></h3>',9)),t("p",null,[s[1]||(s[1]=a("在 Linux 系统安装完成后就已经有很多日志文件被纳入到日志滚动的范围内了。另外，一些应用程序在安装时也会为自己产生的日志文件设置滚动规则。一般来说，日志滚动的配置文件会放置在 ",-1)),s[2]||(s[2]=t("code",null,"/etc/logrotate.d",-1)),s[3]||(s[3]=a("。如果你想了解日志滚动的详细实现，可以参考",-1)),n(l,{href:"https://www.networkworld.com/article/3218728/how-log-rotation-works-with-logrotate.html"},{default:e(()=>[...s[0]||(s[0]=[a("这篇以前的文章",-1)])]),_:1}),s[4]||(s[4]=a("。",-1))]),s[21]||(s[21]=o(`<p>在日志滚动的过程中，活动日志会以一个新名称命名，例如 <code>log.1</code>，之前被命名为 <code>log.1</code> 的文件则会被重命名为 <code>log.2</code>，依此类推。在这一组文件中，最旧的日志文件（假如名为 <code>log.7</code>）会从系统中删除。日志滚动时文件的命名方式、保留日志文件的数量等参数是由 <code>/etc/logrotate.d</code> 目录中的配置文件决定的，因此你可能会看到有些日志文件只保留少数几次滚动，而有些日志文件的滚动次数会到 7 次或更多。</p><p>例如 <code>syslog</code> 在经过日志滚动之后可能会如下所示（注意，行尾的注释部分只是说明滚动过程是如何对文件名产生影响的）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l /var/log/syslog*</span></span>
<span class="line"><span>-rw-r----- 1 syslog adm  128674 Mar 10 08:00 /var/log/syslog      &lt;== 新文件</span></span>
<span class="line"><span>-rw-r----- 1 syslog adm 2405968 Mar  9 16:09 /var/log/syslog.1    &lt;== 之前的 syslog</span></span>
<span class="line"><span>-rw-r----- 1 syslog adm  206451 Mar  9 00:00 /var/log/syslog.2.gz &lt;== 之前的 syslog.1</span></span>
<span class="line"><span>-rw-r----- 1 syslog adm  216852 Mar  8 00:00 /var/log/syslog.3.gz &lt;== 之前的 syslog.2.gz</span></span>
<span class="line"><span>-rw-r----- 1 syslog adm  212889 Mar  7 00:00 /var/log/syslog.4.gz &lt;== 之前的 syslog.3.gz</span></span>
<span class="line"><span>-rw-r----- 1 syslog adm  219106 Mar  6 00:00 /var/log/syslog.5.gz &lt;== 之前的 syslog.4.gz</span></span>
<span class="line"><span>-rw-r----- 1 syslog adm  218596 Mar  5 00:00 /var/log/syslog.6.gz &lt;== 之前的 syslog.5.gz</span></span>
<span class="line"><span>-rw-r----- 1 syslog adm  211074 Mar  4 00:00 /var/log/syslog.7.gz &lt;== 之前的 syslog.6.gz</span></span></code></pre></div><p>你可能会发现，除了当前活动的日志和最新一次滚动的日志文件之外，其余的文件都已经被压缩以节省存储空间。这样设计的原因是大部分系统管理员都只需要查阅最新的日志文件，其余的日志文件压缩起来，需要的时候可以解压查阅，这是一个很好的折中方案。</p><h3 id="手动日志滚动" tabindex="-1">手动日志滚动 <a class="header-anchor" href="#手动日志滚动" aria-label="Permalink to “手动日志滚动”">​</a></h3><p>你可以这样执行 <code>logrotate</code> 命令进行手动日志滚动：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo logrotate -f /etc/logrotate.d/rsyslog</span></span></code></pre></div><p>值得一提的是，<code>logrotate</code> 命令使用 <code>/etc/logrotate.d/rsyslog</code> 这个配置文件，并通过了 <code>-f</code> 参数实行“强制滚动”。因此，整个过程将会是：</p><ul><li>删除 <code>syslog.7.gz</code>，</li><li>将原来的 <code>syslog.6.gz</code> 命名为 <code>syslog.7.gz</code>，</li><li>将原来的 <code>syslog.5.gz</code> 命名为 <code>syslog.6.gz</code>，</li><li>将原来的 <code>syslog.4.gz</code> 命名为 <code>syslog.5.gz</code>，</li><li>将原来的 <code>syslog.3.gz</code> 命名为 <code>syslog.4.gz</code>，</li><li>将原来的 <code>syslog.2.gz</code> 命名为 <code>syslog.3.gz</code>，</li><li>将原来的 <code>syslog.1.gz</code> 命名为 <code>syslog.2.gz</code>，</li><li>但新的 <code>syslog</code> 文件不一定必须创建。</li></ul><p>你可以按照下面的几条命令执行操作，以确保文件的属主和权限正确：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo touch /var/log/syslog</span></span>
<span class="line"><span>$ sudo chown syslog:adm /var/log/syslog</span></span>
<span class="line"><span>$ sudo chmod 640 /var/log/syslog</span></span></code></pre></div><p>你也可以把以下这一行内容添加到 <code>/etc/logrotate.d/rsyslog</code> 当中，由 <code>logrotate</code> 来帮你完成上面三条命令的操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>create 0640 syslog adm</span></span></code></pre></div><p>整个配置文件的内容是这样的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/var/log/syslog</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>rotate 7</span></span>
<span class="line"><span>daily</span></span>
<span class="line"><span>missingok</span></span>
<span class="line"><span>notifempty</span></span>
<span class="line"><span>create 0640 syslog adm           &lt;==</span></span>
<span class="line"><span>delaycompress</span></span>
<span class="line"><span>compress</span></span>
<span class="line"><span>postrotate</span></span>
<span class="line"><span>/usr/lib/rsyslog/rsyslog-rotate</span></span>
<span class="line"><span>endscript</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>下面是手动滚动记录用户登录信息的 <code>wtmp</code> 日志的示例。由于 <code>/etc/logrotate.d/wtmp</code> 中有 <code>rotate 2</code> 的配置，因此系统中只保留了两份 <code>wtmp</code> 日志文件。</p><p>滚动前：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l wtmp*</span></span>
<span class="line"><span>-rw-r----- 1 root utmp  1152 Mar 12 11:49 wtmp</span></span>
<span class="line"><span>-rw-r----- 1 root utmp   768 Mar 11 17:04 wtmp.1</span></span></code></pre></div><p>执行滚动命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo logrotate -f /etc/logrotate.d/wtmp</span></span></code></pre></div><p>滚动后：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l /var/log/wtmp*</span></span>
<span class="line"><span>-rw-r----- 1 root utmp     0 Mar 12 11:52 /var/log/wtmp</span></span>
<span class="line"><span>-rw-r----- 1 root utmp  1152 Mar 12 11:49 /var/log/wtmp.1</span></span>
<span class="line"><span>-rw-r----- 1 root adm  99726 Feb 21 07:46 /var/log/wtmp.report</span></span></code></pre></div><p>需要知道的是，无论发生的日志滚动是自动滚动还是手动滚动，最近一次的滚动时间都会记录在 <code>logrorate</code> 的状态文件中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep wtmp /var/lib/logrotate/status</span></span>
<span class="line"><span>&quot;/var/log/wtmp&quot; 2020-3-12-11:52:57</span></span></code></pre></div><hr>`,25)),t("p",null,[s[6]||(s[6]=a("via: ",-1)),n(l,{href:"https://www.networkworld.com/article/3531969/manually-rotating-log-files-on-linux.html"},{default:e(()=>[...s[5]||(s[5]=[a("https://www.networkworld.com/article/3531969/manually-rotating-log-files-on-linux.html",-1)])]),_:1})]),t("p",null,[s[11]||(s[11]=a("作者：",-1)),n(l,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:e(()=>[...s[7]||(s[7]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[12]||(s[12]=a(" 选题：",-1)),n(l,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[8]||(s[8]=[a("lujun9972",-1)])]),_:1}),s[13]||(s[13]=a(" 译者：",-1)),n(l,{href:"https://github.com/HankChow"},{default:e(()=>[...s[9]||(s[9]=[a("HankChow",-1)])]),_:1}),s[14]||(s[14]=a(" 校对：",-1)),n(l,{href:"https://github.com/wxy"},{default:e(()=>[...s[10]||(s[10]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[17]||(s[17]=a("本文由 ",-1)),n(l,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[15]||(s[15]=[a("LCTT",-1)])]),_:1}),s[18]||(s[18]=a(" 原创编译，",-1)),n(l,{href:"https://linux.cn/"},{default:e(()=>[...s[16]||(s[16]=[a("Linux中国",-1)])]),_:1}),s[19]||(s[19]=a(" 荣誉推出",-1))])])}const x=i(d,[["render",c]]);export{w as __pageData,x as default};
